(function(){'use strict';
/* JAH The Nuclear Physics generator — jahdb-nuclear-physics-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-NUCPH-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Nuclear Physics", "desc": "Nuclear physics studies the atomic nucleus: protons and neutrons bound by the strong force into a femtometer-scale object containing 99.97% of atomic mass. It explains radioactivity, nuclear energy, stellar burning, and the origin of the elements.\nBorn in 1911 with Rutherford's scattering experiment and matured through the 20th century (fission 1938, fusion theory, shell model 1949), it underpins power reactors, medicine, dating, and astrophysics - while its weapons shadow demands sober treatment.", "how": "Approach nuclei by A (mass number), Z (protons), N (neutrons): notation ᴬZX. Compute energetics from masses (E = Δmc²); classify decays by conservation laws; model structure with liquid-drop and shell pictures. Always track energy, charge, and nucleon number.", "keys": ["Nucleus: fm scale, ~all atomic mass.", "Explains radioactivity, energy, stellar burning.", "Born 1911 (Rutherford); fission 1938.", "Notation ᴬZX: A nucleons, Z protons.", "Conservation laws govern all decays."], "reqs": ["A, Z, N assignment.", "Mass data for energetics.", "Conservation-law checks."], "stds": ["Masses in u; energies in MeV.", "ᴬZX notation."], "cites": ["Krane KS. Introductory Nuclear Physics. Wiley; 1987.", "Rutherford E. Phil Mag 1911;21:669-688."], "demo": "#!/usr/bin/env python3\n\"\"\"Nucleon inventory from ᴬZX.\"\"\"\ndef nucleons(A, Z):\n    return {\"protons\": Z, \"neutrons\": A-Z, \"nucleons\": A}\nfor A, Z in [(238, 92), (12, 6), (56, 26)]:\n    print(f\"  A={A} Z={Z}: {nucleons(A, Z)}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Discovery of the Nucleus (Rutherford)", "desc": "In 1909 Geiger and Marsden fired alpha particles at gold foil; most passed through, but 1 in 8000 bounced back - Rutherford (1911): the atom is mostly empty space with a tiny, massive, positive nucleus. 'It was as if you fired a shell at tissue paper and it bounced back.'\nThe scattering formula (dσ/dΩ ∝ 1/sin⁴(θ/2)) matched a point charge - measuring nuclear charge. The plum-pudding model died; the nuclear atom was born, with electrons' arrangement left to Bohr (1913) and quantum mechanics.", "how": "Apply Rutherford's formula for scattering angles and cross sections. Estimate nuclear size from closest approach (d = 2kZ₁Z₂e²/E). Recognize the experiment's logic: large-angle scattering requires concentrated charge - the signature of the nucleus.", "keys": ["Alpha backscattering proved the nucleus (1911).", "Atom: mostly empty space, tiny massive core.", "dσ/dΩ proportional to 1/sin⁴(θ/2).", "Measured nuclear charge directly.", "Killed the plum-pudding model."], "reqs": ["Alpha energy and target Z.", "Scattering-angle data.", "Point-charge approximation."], "stds": ["Cross sections in barns.", "Angles in degrees."], "cites": ["Rutherford E. Phil Mag 1911;21:669-688.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Rutherford closest approach.\"\"\"\ndef closest_approach_fm(Z1, Z2, E_MeV):\n    return 2*1.44*Z1*Z2/E_MeV\nprint(f\"  α on Au, 7.7 MeV: {closest_approach_fm(2, 79, 7.7):.1f} fm\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Nuclear Notation: Z, A, Isotopes", "desc": "ᴬZX: A = mass number (protons + neutrons), Z = atomic number (protons, sets the element), N = A - Z neutrons. Isotopes share Z, differ in N: ¹²C/¹³C/¹⁴C. Isotones share N; isobars share A.\nHydrogen's isotopes have names (protium, deuterium, tritium); others use mass numbers (uranium-235). Stable nuclei (~270) vs radioactive (~3000 known): the chart of nuclides maps them all, with magic numbers marking extra stability.", "how": "Read ᴬZX: protons = Z, neutrons = A - Z. Classify isotope/isotone/isobar relationships. Locate on the chart of nuclides; check stability via the band of stability. Name isotopes as element-mass number (carbon-14).", "keys": ["ᴬZX: A total nucleons, Z protons.", "Isotopes: same Z, different N.", "Isotones: same N; isobars: same A.", "~270 stable, ~3000 radioactive known.", "Chart of nuclides maps them all."], "reqs": ["A and Z.", "Chart position.", "Stability check."], "stds": ["Isotope names as element-A.", "N = A - Z explicit."], "cites": ["Krane KS. Introductory Nuclear Physics. Wiley; 1987.", "NNDC. Chart of Nuclides (Brookhaven)."], "demo": "#!/usr/bin/env python3\n\"\"\"Isotope/isobar/isotone classifier.\"\"\"\ndef relation(n1, n2):\n    A1,Z1 = n1; A2,Z2 = n2\n    if Z1==Z2 and A1!=A2: return \"isotopes\"\n    if A1-Z1==A2-Z2 and Z1!=Z2: return \"isotones\"\n    if A1==A2 and Z1!=Z2: return \"isobars\"\n    return \"unrelated\"\nprint(\"  ¹²C vs ¹⁴C:\", relation((12,6),(14,6)))\nprint(\"  ¹⁴C vs ¹⁴N:\", relation((14,6),(14,7)))\n"}, {"tier": "Foundations", "g": "Structure", "title": "Nuclear Size and Density", "desc": "Nuclei are ~femtometers: R ≈ r₀A^(1/3) with r₀ = 1.2 fm - volume proportional to A, so nuclear density is constant (~2.3×10¹⁷ kg/m³, staggering). Electron scattering (Hofstadter, Nobel 1961) mapped charge distributions.\nA teaspoon of nuclear matter would weigh billions of tons - neutron stars are macroscopic nuclei. The A^(1/3) law is liquid-drop evidence: nucleons pack like an incompressible fluid.", "how": "Estimate R = 1.2·A^(1/3) fm. Compute density from mass/volume - verify constancy across A. Compare to atomic sizes (10⁵× larger) for the emptiness of atoms. Reference electron-scattering form factors for charge radii.", "keys": ["R ≈ 1.2·A^(1/3) fm.", "Density ~2.3×10¹⁷ kg/m³, constant.", "Volume proportional to A (liquid-like).", "Atoms are 10⁵× larger than nuclei.", "Hofstadter mapped charge (Nobel 1961)."], "reqs": ["Mass number A.", "Charge-radius data if precise.", "Spherical approximation noted."], "stds": ["Radii in fm.", "Density in kg/m³."], "cites": ["Hofstadter R. Rev Mod Phys 1956;28:214-254.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Nuclear radii across the table.\"\"\"\ndef R(A):\n    return 1.2*A**(1/3)\nfor name, A in [(\"¹²C\", 12), (\"⁵⁶Fe\", 56), (\"²³⁸U\", 238)]:\n    print(f\"  {name}: R ≈ {R(A):.1f} fm\")\n"}, {"tier": "Foundations", "g": "Structure", "title": "Binding Energy and the Mass Defect", "desc": "Nuclei weigh less than their parts: the missing mass (Δm) is binding energy via E = Δmc² (1 u = 931.5 MeV). ⁴He's 28.3 MeV binding (0.7% of mass) comes from assembling 2p + 2n - the mass defect is the bond.\nAston's mass spectrograph (1919) measured the defects; Einstein's relation gave the energy. Every nuclear reaction's Q-value is a mass difference - weigh before and after, multiply by c².", "how": "Compute BE = [Zm_p + Nm_n - M_nucleus]c². Convert with 931.5 MeV/u. Get Q-values from mass tables (Q = (m_initial - m_final)c²; Q > 0 exothermic). Use atomic masses carefully - electron masses cancel when Z balances.", "keys": ["Δm·c² = binding energy.", "1 u = 931.5 MeV.", "⁴He: 28.3 MeV bound.", "Q-values from mass differences.", "Aston measured; Einstein explained."], "reqs": ["Nuclear (or atomic, Z-balanced) masses.", "Conversion 931.5 MeV/u.", "Sign convention for Q."], "stds": ["Masses in u; energies in MeV.", "Q > 0 exothermic."], "cites": ["Aston FW. Phil Mag 1920;39:611-625.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Q-value from masses (u).\"\"\"\ndef Q(m_in, m_out):\n    return (m_in-m_out)*931.5\n# d + t -> α + n\nprint(f\"  D-T fusion Q ≈ {Q(2.014102+3.016049, 4.002603+1.008665):.1f} MeV\")\n"}, {"tier": "Foundations", "g": "Structure", "title": "The Curve of Binding Energy", "desc": "Binding energy per nucleon peaks at iron-56 (~8.8 MeV) - the most stable nucleus. Lighter nuclei fuse upward toward iron (stars, H-bombs); heavier split downward (fission, reactors, A-bombs). The curve is why both fusion and fission release energy.\n⁴He, ¹²C, ¹⁶O spike high (alpha-cluster structure); the curve's shape comes from competing volume, surface, Coulomb, asymmetry, and pairing terms - the semi-empirical mass formula quantifies each.", "how": "Read BE/A vs A: peak at Fe-56. Predict energy release: fuse light or split heavy toward iron. Fit the semi-empirical mass formula to extract the five terms. Explain anomalies (⁴He spike) via clustering/shell effects.", "keys": ["Peak at ⁵⁶Fe (~8.8 MeV/nucleon).", "Fuse light, split heavy - both head for iron.", "The curve explains all nuclear energy.", "⁴He/¹²C/¹⁶O spikes: alpha clustering.", "Five-term mass formula fits it."], "reqs": ["BE/A data vs A.", "Mass-formula terms.", "Reaction direction (fuse/split)."], "stds": ["BE/A in MeV/nucleon.", "⁵⁶Fe as the reference maximum."], "cites": ["Weizsäcker CF. Z Phys 1935;96:431-458.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"BE/A landmarks.\"\"\"\ndata = [(\"²H\", 1.1), (\"⁴He\", 7.1), (\"¹²C\", 7.7), (\"⁵⁶Fe\", 8.8), (\"²³⁸U\", 7.6)]\nfor name, be in data:\n    print(f\"  {name:6s}: {be} MeV/nucleon\")\n"}, {"tier": "Foundations", "g": "Radioactivity", "title": "Radioactivity: Alpha, Beta, Gamma", "desc": "Becquerel (1896, uranium fogging plates), the Curies, Rutherford: three radiations. Alpha: ⁴He nuclei, heavy, short range (paper stops), from heavy nuclei. Beta: electrons/positrons from weak-force nucleon conversion, medium range. Gamma: photons from excited nuclei, penetrating (lead needed).\nEach changes the nucleus differently: α loses 2p2n, β⁻ converts n→p (Z+1), β⁺/EC converts p→n (Z-1), γ just de-excites. Conservation laws (energy, charge, nucleon number, lepton number) govern all.", "how": "Identify radiation by penetrating power and charge. Write decays balancing A and Z (and lepton number for β). Predict α for heavy nuclei (A > 200), β for off-stability-line nuclei, γ following other decays. Shield: paper/skin (α), aluminum (β), lead (γ).", "keys": ["α: ⁴He, short range; β: electrons, medium; γ: photons, penetrating.", "Becquerel 1896; Curies; Rutherford classified.", "α: -2p2n; β⁻: n→p; β⁺: p→n; γ: de-excitation.", "Shielding: paper, aluminum, lead.", "Conservation laws govern every decay."], "reqs": ["Parent/daughter A, Z.", "Radiation identification.", "Lepton-number balance for β."], "stds": ["Decays written with A, Z balanced.", "Energies in MeV/keV."], "cites": ["Becquerel H. C R Acad Sci 1896;122:420-421.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Decay mode classifier (toy).\"\"\"\ndef mode(A, n_excess):\n    if A > 200: return \"alpha likely\"\n    return \"beta- (neutron-rich)\" if n_excess > 0 else \"beta+ or EC (proton-rich)\"\nprint(\"  ²³⁸U:\", mode(238, 0))\nprint(\"  ¹⁴C:\", mode(14, 2))\n"}, {"tier": "Foundations", "g": "Radioactivity", "title": "The Decay Law and Half-Life", "desc": "dN/dt = -λN: decay is statistical - each nucleus has constant probability λ per time, giving N = N₀e^(-λt). Half-life t½ = ln2/λ: ¹⁴C 5730 years (dating), ²³⁸U 4.5 billion years (Earth's age), ²¹²Po 0.3 microseconds.\nActivity A = λN (becquerels). After 10 half-lives, 1/1024 remains - the rule of thumb for 'gone'. Secular equilibrium: long-lived parents sustain short-lived daughters (²²⁶Ra → ²²²Rn chains).", "how": "Compute λ = ln2/t½; N(t) = N₀e^(-λt). Convert activity to atoms (N = A/λ) for source strengths. Apply 10-half-life rule for decay-away. Set up secular equilibrium (daughter activity = parent) for chains.", "keys": ["N = N₀e^(-λt); t½ = ln2/λ.", "Decay is statistical per-nucleus.", "Activity in becquerels (decays/s).", "10 half-lives ≈ gone (1/1024).", "Secular equilibrium in chains."], "reqs": ["Half-life or λ.", "Initial quantity.", "Time interval."], "stds": ["t½ with units; λ in s⁻¹.", "Activity in Bq (or Ci)."], "cites": ["Rutherford E, Soddy F. Phil Mag 1902;4:370-396.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Remaining fraction after n half-lives.\"\"\"\ndef frac(n):\n    return 0.5**n\nfor n in (1, 5, 10):\n    print(f\"  {n:2d} half-lives: {frac(n):.4f} remains\")\n"}, {"tier": "Foundations", "g": "Radioactivity", "title": "Units: Becquerel, Gray, Sievert", "desc": "Becquerel (Bq): decays per second - activity. Gray (Gy): joules per kg absorbed - dose. Sievert (Sv): dose × quality factor - biological effect (α × 20, γ × 1). Bananas (~15 Bq ⁴⁰K) vs CT scans (~10 mSv): the units separate physics from biology.\nBackground ~2.4 mSv/year (cosmic, radon, food). Limits: public 1 mSv/year above background; workers 50 mSv/year. LNT vs threshold models debate low-dose risk - the units don't settle the biology.", "how": "Report activity in Bq, absorbed dose in Gy, effective dose in Sv - never mix them. Apply quality factors for dose equivalent. Compare to background (2.4 mSv/yr) for context. Follow ALARA (as low as reasonably achievable) in practice.", "keys": ["Bq: decays/s; Gy: J/kg; Sv: biological dose.", "Quality factors: α 20×, γ 1×.", "Background ~2.4 mSv/year.", "Units separate physics from biology.", "ALARA guides practice."], "reqs": ["Radiation type and energy.", "Exposure geometry.", "Quality factor applied."], "stds": ["Bq, Gy, Sv - never mixed.", "Background cited for context."], "cites": ["ICRP Publication 103. 2007.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Dose context (mSv).\"\"\"\ndoses = [(\"background/yr\", 2.4), (\"chest X-ray\", 0.1), (\"CT abdomen\", 10), (\"worker limit/yr\", 50)]\nfor name, d in doses:\n    print(f\"  {name:16s}: {d} mSv\")\n"}, {"tier": "Foundations", "g": "Stability", "title": "Nuclear Stability and the Band of Stability", "desc": "Stable nuclei cluster on N/Z ≈ 1 (light) rising to ~1.5 (heavy - extra neutrons dilute Coulomb repulsion). Off the band, nuclei β-decay back toward it: neutron-rich → β⁻, proton-rich → β⁺/EC.\nThe drip lines bound existence: add one more nucleon and it falls off (unbound). ~270 stable nuclides sit in the band; ~3000 radioactive ones surround it - the chart of nuclides' geography.", "how": "Plot N vs Z; check position relative to the stability band. Predict decay direction (toward the band). Locate drip lines from separation energies (S_n, S_p < 0 = unbound). Use the band for isotope-production targeting.", "keys": ["N/Z ≈ 1 light, ≈ 1.5 heavy.", "Off-band nuclei β-decay back.", "Drip lines bound existence.", "~270 stable of ~3000+ known.", "Coulomb vs asymmetry sets the band."], "reqs": ["N, Z.", "Separation energies.", "Chart position."], "stds": ["N/Z ratios stated.", "Drip lines from S < 0."], "cites": ["Krane KS. Introductory Nuclear Physics. Wiley; 1987.", "NNDC. Chart of Nuclides (Brookhaven)."], "demo": "#!/usr/bin/env python3\n\"\"\"N/Z ratios across the table.\"\"\"\nfor name, N, Z in [(\"¹²C\", 6, 6), (\"⁵⁶Fe\", 30, 26), (\"²⁰⁸Pb\", 126, 82), (\"²³⁸U\", 146, 92)]:\n    print(f\"  {name:6s}: N/Z = {N/Z:.2f}\")\n"}, {"tier": "Foundations", "g": "Stability", "title": "Natural Radioactive Series", "desc": "Three primordial chains: ²³⁸U → ²⁰⁶Pb (4n+2), ²³⁵U → ²⁰⁷Pb (4n+3), ²³²Th → ²⁰⁸Pb (4n) - each ~14 steps of α/β through radium, radon, polonium. The 4n+1 (neptunium) series is extinct - its 2-million-year half-life couldn't survive Earth's age.\n²²²Rn (radon gas, 3.8-day half-life) seeps from uranium soils into homes - the second cause of lung cancer. Secular equilibrium makes daughters track parents; breaking it (radon escaping) enables dating and detection.", "how": "Trace chains step by step (α: -4,-2; β: +1 Z). Identify radon as the mobile hazard; test homes in uranium regions. Use disequilibrium (²³⁴U/²³⁸U, ²¹⁰Pb) for dating young sediments. Account for the missing 4n+1 series in primordial inventories.", "keys": ["Three chains: 4n+2, 4n+3, 4n series.", "End at lead isotopes.", "²²²Rn: the mobile lung-cancer hazard.", "4n+1 extinct (too short-lived).", "Disequilibrium enables dating."], "reqs": ["Chain membership (4n+k).", "Step-by-step A, Z.", "Radon emanation considered."], "stds": ["Chains written stepwise.", "Half-lives per member."], "cites": ["Krane KS. Introductory Nuclear Physics. Wiley; 1987.", "EPA. Radon guidance."], "demo": "#!/usr/bin/env python3\n\"\"\"U-238 chain start.\"\"\"\nchain = [\"²³⁸U\", \"²³⁴Th (β-)\", \"²³⁴Pa (β-)\", \"²³⁴U (α)\", \"²³⁰Th (α)\", \"²²⁶Ra (α)\", \"²²²Rn (α)\"]\nprint(\"  \" + \" → \".join(chain) + \" → ... → ²⁰⁶Pb\")\n"}, {"tier": "Compounded", "g": "Decay", "title": "Alpha Decay Theory (Gamow)", "desc": "Alpha decay: the α particle rattles inside the nucleus, hits the Coulomb barrier ~10²¹ times/second, and tunnels out with probability e^(-2G) - Gamow (1928) explained the Geiger-Nuttall law (log t½ ∝ 1/√Q) as quantum tunneling. One of quantum mechanics' first triumphs.\nThe extreme Q-sensitivity: tiny energy changes mean billion-fold half-life differences (²¹²Po 0.3 µs vs ²³²Th 14 Gyr). Tunneling also runs fusion in stars and scanning tunneling microscopes - the same physics.", "how": "Compute the Gamow factor G from Z, Q, and radius; estimate t½ from assault frequency × tunneling probability. Verify Geiger-Nuttall systematics within an isotopic chain. Remember: tunneling is exponentially sensitive - small Q errors, huge t½ errors.", "keys": ["Tunneling through the Coulomb barrier.", "Gamow 1928 explained Geiger-Nuttall.", "Assault frequency ~10²¹ /s.", "Extreme Q-sensitivity of half-lives.", "Quantum mechanics' early triumph."], "reqs": ["Q-value (precise).", "Daughter Z.", "Nuclear radius."], "stds": ["t½ with Q cited.", "Gamow factor dimensionless."], "cites": ["Gamow G. Z Phys 1928;51:204-212.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Geiger-Nuttall: log t½ vs 1/sqrt(Q).\"\"\"\nimport math\ndef logt(Q_MeV, a=150, b=-55):\n    return a/math.sqrt(Q_MeV) + b\nfor Q in (4.0, 6.0, 9.0):\n    print(f\"  Q={Q} MeV: log10(t½/s) ≈ {logt(Q):.1f}\")\n"}, {"tier": "Compounded", "g": "Decay", "title": "Beta Decay and the Weak Force", "desc": "β⁻: n → p + e⁻ + ν̄_e; β⁺: p → n + e⁺ + ν_e; electron capture: p + e⁻ → n + ν_e. The continuous electron spectrum (not monoenergetic) forced Pauli's 1930 neutrino hypothesis - 'I have done a terrible thing' - confirmed by Cowan and Reines (1956, Nobel 1995).\nFermi's 1934 theory made it the weak interaction: W bosons mediate, quarks change flavor (d → u). Selection rules (Fermi vs Gamow-Teller, allowed/forbidden) set lifetimes; the weak force also powers the Sun's first step (p + p → d).", "how": "Write decays conserving A, Z, charge, lepton number (neutrino included). Classify Fermi (ΔJ = 0, no parity change) vs Gamow-Teller (ΔJ = 0,±1). Estimate phase space (∝ Q⁵ for allowed) - the lifetime's main lever. Include EC competition at low Q.", "keys": ["n→p (β⁻), p→n (β⁺/EC): weak-force flavor change.", "Neutrino hypothesized 1930, found 1956.", "Continuous spectrum proved the neutrino.", "Fermi vs Gamow-Teller selection rules.", "Weak force starts solar fusion."], "reqs": ["Q-value and decay scheme.", "Spin-parity of states.", "Lepton-number balance."], "stds": ["ft values (comparative half-lives).", "Branching ratios."], "cites": ["Fermi E. Z Phys 1934;88:161-177.", "Cowan CL et al. Science 1956;124:103-104."], "demo": "#!/usr/bin/env python3\n\"\"\"Beta-decay Q⁵ phase-space scaling.\"\"\"\ndef rate_scale(Q):\n    return Q**5\nprint(f\"  Q=1 vs Q=2: rate ratio {rate_scale(2)/rate_scale(1):.0f}x\")\n"}, {"tier": "Compounded", "g": "Decay", "title": "Gamma Transitions and Selection", "desc": "Excited nuclei shed energy as γ photons (keV-MeV): multipolarity (E1, M1, E2...) from angular-momentum selection (|ΔJ| ≤ L ≤ J_i + J_f); electric vs magnetic from parity change. Lifetimes span femtoseconds to years - isomers (²ᵐTc 6 h, the medical workhorse; ¹⁸⁰ᵐTa, nature's rarest).\nInternal conversion competes (eject an atomic electron instead of γ); pair production above 1.022 MeV. Mössbauer's recoil-free γ's (1961 Nobel) reach neV resolution - hyperfine interactions measurable.", "how": "Assign multipolarity from ΔJ and parity (E vs M). Estimate lifetimes by Weisskopf single-particle rates - deviations signal collectivity. Identify isomers (metastable states); use ⁹⁹ᵐTc's 140 keV γ for imaging. Consider internal conversion coefficients for low-energy transitions.", "keys": ["Multipolarity from ΔJ and parity.", "E1 fastest; higher L slower.", "Isomers: long-lived excited states.", "⁹⁹ᵐTc: medicine's γ source.", "Internal conversion competes."], "reqs": ["Level scheme (spins, parities).", "Transition energy.", "Conversion coefficients."], "stds": ["Multipolarity (E1, M1, E2...).", "Lifetimes with units."], "cites": ["Krane KS. Introductory Nuclear Physics. Wiley; 1987.", "Mössbauer RL. Z Phys 1958;151:124-143."], "demo": "#!/usr/bin/env python3\n\"\"\"Weisskopf lifetime scaling vs multipolarity.\"\"\"\nscales = {\"E1\": 1e-15, \"M1\": 1e-13, \"E2\": 1e-9, \"M2\": 1e-7}\nfor mp, t in scales.items():\n    print(f\"  {mp}: ~{t:.0e} s (1 MeV, A=100 scale)\")\n"}, {"tier": "Compounded", "g": "Models", "title": "The Liquid Drop Model", "desc": "Nucleus as a charged liquid drop: volume term (a_v A - each nucleon bound), surface term (-a_s A^(2/3) - surface nucleons less bound), Coulomb (-a_c Z²/A^(1/3) - proton repulsion), asymmetry (-a_a (N-Z)²/A - Pauli cost), pairing (+δ - even-even bonus). Five terms fit masses to ~MeV.\nWeizsäcker (1935), Bohr-Wheeler (1939): fission as drop deformation - Coulomb vs surface tension, the fissility parameter Z²/A > ~48 means spontaneous fission. The model nails bulk trends, misses shell wiggles - its complement, not competitor.", "how": "Compute masses/BE from the five terms; fit coefficients to data. Evaluate fissility Z²/A for fission tendency. Use for bulk predictions (Q-values, drip lines); switch to shell model for magic-number effects.", "keys": ["Five terms: volume, surface, Coulomb, asymmetry, pairing.", "Weizsäcker 1935; Bohr-Wheeler fission 1939.", "Z²/A > ~48: spontaneous fission.", "Fits bulk masses; misses shells.", "Fission as drop deformation."], "reqs": ["A, Z.", "Coefficient set cited.", "Deformation if fissioning."], "stds": ["Coefficients in MeV.", "Fissility dimensionless."], "cites": ["Weizsäcker CF. Z Phys 1935;96:431-458.", "Bohr N, Wheeler JA. Phys Rev 1939;56:426-450."], "demo": "#!/usr/bin/env python3\n\"\"\"Fissility parameter Z²/A.\"\"\"\ndef fissility(Z, A):\n    return Z*Z/A\nfor name, Z, A in [(\"²³⁵U\", 92, 235), (\"²³⁹Pu\", 94, 239), (\"²⁵²Cf\", 98, 252)]:\n    print(f\"  {name}: {fissility(Z, A):.1f}\")\n"}, {"tier": "Compounded", "g": "Models", "title": "The Nuclear Shell Model", "desc": "Nucleons orbit in a mean-field potential (Woods-Saxon) with strong spin-orbit coupling (Mayer, Jensen, Nobel 1963): magic numbers 2, 8, 20, 28, 50, 82, 126 - closed shells, extra stability (⁴He, ¹⁶O, ²⁰⁸Pb doubly magic). It predicts spins, parities, magnetic moments.\nEach nucleon gets n, l, j = l ± ½; fill like atomic shells. The model explains ground-state properties beautifully and collective rotation/vibration poorly - the liquid drop's mirror image. Modern large-scale shell model diagonalizes millions of configurations.", "how": "Fill levels in spin-orbit order; the last unpaired nucleon sets spin-parity (extreme single-particle). Check magic numbers for stability anomalies. Predict magnetic moments (Schmidt lines) - deviations signal configuration mixing. Use for near-closed-shell nuclei.", "keys": ["Spin-orbit coupling makes the magic numbers.", "2, 8, 20, 28, 50, 82, 126.", "Mayer/Jensen Nobel 1963.", "Predicts spins, parities, moments.", "Complements the liquid drop."], "reqs": ["Nucleon filling order.", "Last-nucleon assignment.", "Closed-shell check."], "stds": ["Levels labeled n l_j.", "Spins/parities as J^π."], "cites": ["Mayer MG, Jensen JHD. Elementary Theory of Nuclear Shell Structure. Wiley; 1955.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Magic-number check.\"\"\"\nmagic = {2, 8, 20, 28, 50, 82, 126}\ndef magic_check(Z, N):\n    return [x for x in (f\"Z={Z}\", f\"N={N}\") if int(x.split(\"=\")[1]) in magic]\nprint(\"  ²⁰⁸Pb:\", magic_check(82, 126), \"(doubly magic)\")\nprint(\"  ⁵⁶Fe:\", magic_check(26, 30))\n"}, {"tier": "Compounded", "g": "Models", "title": "Nuclear Spin and Magnetic Moments", "desc": "Nuclear spin I (units ħ) and magnetic moment μ = g·I·μ_N: even-even nuclei 0⁺ (paired nucleons cancel); odd-A from the last nucleon (shell model). Deuteron's small quadrupole moment proved the nuclear force is non-central (tensor component).\nNMR/MRI exploit nuclear moments (¹H, ¹³C); hyperfine splitting in atomic spectra comes from them. Schmidt lines bound single-particle moments - measured values between the lines reveal collective contributions.", "how": "Assign I^π: even-even → 0⁺; odd-A → last nucleon j^π. Compare μ to Schmidt lines for configuration purity. Use quadrupole moments for deformation (prolate/oblate). Apply to NMR: resonance at ω = γB₀.", "keys": ["Even-even: 0⁺ ground states.", "Odd-A spin from last nucleon.", "Deuteron quadrupole: tensor force proof.", "μ_N = eħ/2m_p: the nuclear magneton.", "Moments enable NMR/MRI."], "reqs": ["A, Z parity (even/odd).", "Last-nucleon configuration.", "Measured μ for comparison."], "stds": ["Spins as I^π; μ in μ_N.", "Schmidt lines cited."], "cites": ["Krane KS. Introductory Nuclear Physics. Wiley; 1987.", "Mayer MG, Jensen JHD. Elementary Theory of Nuclear Shell Structure. Wiley; 1955."], "demo": "#!/usr/bin/env python3\n\"\"\"Ground-state spin predictions.\"\"\"\ndef spin(A, Z):\n    if A % 2 == 0 and Z % 2 == 0: return \"0+\"\n    return \"last-nucleon j^π (shell model)\"\nfor A, Z in [(12, 6), (13, 6), (56, 26)]:\n    print(f\"  A={A}: {spin(A, Z)}\")\n"}, {"tier": "Compounded", "g": "Reactions", "title": "Nuclear Reactions: Q-Values", "desc": "Reactions: a + X → Y + b, Q = (m_a + m_X - m_Y - m_b)c². Exothermic (Q > 0) runs freely; endothermic needs threshold energy (lab frame: E_thr = -Q(1 + m_a/m_X) - momentum conservation taxes). Compound-nucleus vs direct reactions: slow equilibration vs fast grazing.\nNotation ¹⁴N(α,p)¹⁷O: Rutherford's 1919 transmutation (first artificial). Cross sections (barns) measure probability; resonances spike them - Breit-Wigner shapes.", "how": "Compute Q from mass tables; determine threshold for Q < 0. Classify compound (resonances, symmetric angular distribution) vs direct (forward-peaked, fast). Measure excitation functions (σ vs E); fit resonances with Breit-Wigner.", "keys": ["Q from mass differences; Q > 0 exothermic.", "Threshold: E_thr = -Q(1 + m_a/m_X).", "Compound vs direct mechanisms.", "Cross sections in barns.", "¹⁴N(α,p)¹⁷O: first transmutation (1919)."], "reqs": ["Masses of all participants.", "Lab vs CM frame specified.", "Angular distributions for mechanism."], "stds": ["Q in MeV; σ in barns.", "Threshold in lab frame."], "cites": ["Rutherford E. Phil Mag 1919;37:581-587.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Threshold energy for endothermic reaction.\"\"\"\ndef threshold(Q_MeV, m_a, m_X):\n    return -Q_MeV*(1 + m_a/m_X)\nprint(f\"  Q=-2 MeV, p on ¹²C: E_thr = {threshold(-2, 1, 12):.2f} MeV\")\n"}, {"tier": "Compounded", "g": "Reactions", "title": "Cross Sections", "desc": "σ measures reaction probability as an area: 1 barn = 10⁻²⁸ m² (big as a barn door, physicists joked). ¹⁰B(n,α) has 3840 barns thermal; ²³⁵U fission 585 barns - huge. Resonances (compound-nucleus levels) spike σ by orders of magnitude.\n1/v law: slow neutrons capture better (longer interaction time). Macroscopic Σ = Nσ governs attenuation (I = I₀e^(-Σx)) - shielding design. Measured by transmission, activation, and time-of-flight.", "how": "Look up σ(E) (ENDF database); integrate over spectra for rates (R = N∫σφdE). Apply 1/v extrapolation for thermal neutrons. Design shielding with Σ and tenth-value layers. Fit resonances with Breit-Wigner (E₀, Γ).", "keys": ["1 barn = 10⁻²⁸ m².", "Resonances spike cross sections.", "1/v law favors slow neutrons.", "Σ = Nσ: macroscopic attenuation.", "ENDF: the evaluated data library."], "reqs": ["Neutron energy spectrum.", "σ(E) data.", "Target number density."], "stds": ["σ in barns; Σ in cm⁻¹.", "ENDF citations."], "cites": ["ENDF/B-VIII.0. Nucl Data Sheets 2018;148:1-142.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Attenuation through shielding.\"\"\"\nimport math\ndef transmitted(x_cm, Sigma):\n    return math.exp(-Sigma*x_cm)\nprint(f\"  Σ=0.5/cm, 10 cm: {transmitted(10, 0.5)*100:.1f}% transmitted\")\n"}, {"tier": "Compounded", "g": "Reactions", "title": "Compound Nucleus Reactions", "desc": "Bohr (1936): the projectile merges, energy equilibrates among all nucleons, then the compound nucleus decays - forgetting how it formed (independence hypothesis). Lifetimes ~10⁻¹⁶ s; decay by particle evaporation or fission.\nSignatures: symmetric angular distributions, resonance structure, evaporation spectra (Maxwellian). Hauser-Feshbach theory predicts cross sections statistically. Heavy-ion fusion makes superheavy elements via compound nuclei (⁴⁸Ca + actinides → Z = 114-118).", "how": "Check independence: same compound nucleus from different entrances → same decay. Fit evaporation spectra (nuclear temperature). Use Hauser-Feshbach for statistical cross sections. For superheavies, balance fusion probability against fission (survival).", "keys": ["Bohr 1936: merge, equilibrate, decay.", "Forgets formation (independence).", "Symmetric angles; evaporation spectra.", "Hauser-Feshbach: statistical theory.", "Route to superheavy elements."], "reqs": ["Excitation energy.", "Entrance-channel comparison.", "Level-density parameters."], "stds": ["Excitation in MeV.", "Cross sections in mb/barns."], "cites": ["Bohr N. Nature 1936;137:344-348.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Compound-nucleus excitation energy.\"\"\"\ndef E_star(Q_fusion_MeV, E_cm):\n    return Q_fusion_MeV + E_cm\nprint(f\"  Q=30 MeV + E_cm=200 MeV: E* = {E_star(30, 200)} MeV\")\n"}, {"tier": "Compounded", "g": "Fission", "title": "Fission: Discovery and Mechanism", "desc": "Hahn and Strassmann (1938) found barium in neutron-bombarded uranium; Meitner and Frisch (1939) interpreted: the nucleus splits - fission - releasing ~200 MeV (Coulomb repulsion of fragments). Bohr-Wheeler's liquid-drop theory followed within months.\nAsymmetric mass split (peaks ~95, ~140) from shell effects; 2-3 neutrons + γ's per fission; fragments neutron-rich (β-decay chains). Spontaneous fission competes in the heaviest nuclei - the limit of the periodic table.", "how": "Compute Q from fragment masses (~200 MeV for ²³⁵U). Predict asymmetric yields from shell-corrected potential surfaces. Count neutrons (ν̄ ≈ 2.4 for ²³⁵U) for criticality. Track fragment β-decay chains for decay heat.", "keys": ["Hahn/Strassmann 1938; Meitner/Frisch interpretation.", "~200 MeV per fission.", "Asymmetric split (~95/~140).", "2-3 neutrons emitted.", "Bohr-Wheeler liquid-drop theory."], "reqs": ["Fissile/fertile identification.", "Fragment mass data.", "Neutron multiplicity."], "stds": ["Energies in MeV.", "ν̄ dimensionless."], "cites": ["Hahn O, Strassmann F. Naturwiss 1939;27:11-15.", "Meitner L, Frisch OR. Nature 1939;143:239-240."], "demo": "#!/usr/bin/env python3\n\"\"\"Fission energy vs chemical (per kg U-235).\"\"\"\nE_MeV = 200\nper_kg = E_MeV*1.602e-13*6.022e23/0.235\nprint(f\"  ~{per_kg/1e12:.1f} TJ/kg (vs coal ~0.00003 TJ/kg)\")\n"}, {"tier": "Compounded", "g": "Fusion", "title": "Fusion in Stars", "desc": "Stars fuse light nuclei: the pp chain (Sun: 4p → ⁴He + 26.7 MeV, via weak-force first step - why the Sun burns slowly) and CNO cycle (massive stars, carbon-catalyzed). Energy generation ε ∝ T⁴ (pp) to T²⁰ (CNO) - extreme temperature sensitivity.\nBeyond iron, fusion consumes energy - supernovae forge heavy elements by rapid neutron capture (r-process) instead. The Sun converts 600 million tons of H per second (4 million tons to energy) - Bethe worked out the cycles (Nobel 1967).", "how": "Identify the burning stage by core T (H → He → C → ... → Fe). Compute energy per reaction from masses. Apply ε(T) scalings for stellar models. Trace element origins: Big Bang (H, He), stars (C-Fe), supernovae/neutron mergers (heavier).", "keys": ["pp chain (Sun) vs CNO (massive stars).", "4p → ⁴He + 26.7 MeV.", "ε extremely T-sensitive.", "Iron: fusion's endpoint.", "Supernovae forge heavy elements."], "reqs": ["Core temperature/density.", "Reaction network.", "Weak-rate inputs for pp."], "stds": ["Energies in MeV.", "ε in W/kg."], "cites": ["Bethe HA. Phys Rev 1939;55:434-456.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Solar fusion rate from luminosity.\"\"\"\nL = 3.828e26  # W\nE_per = 26.7*1.602e-13  # J per 4p\nrate = L/E_per\nprint(f\"  {rate:.2e} fusions/s; H consumed: {rate*4*1.67e-27:.2e} kg/s\")\n"}, {"tier": "Compounded", "g": "Applied", "title": "Artificial Radioactivity", "desc": "Joliot-Curies (1934): α + ²⁷Al → ³⁰P + n - the first artificial radioisotope. Reactors (neutron activation) and accelerators (charged-particle reactions) now make thousands: ⁹⁹Mo/⁹⁹ᵐTc (imaging), ⁶⁰Co (therapy), ¹⁸F (PET), ²⁴¹Am (smoke detectors).\nProduction: (n,γ) in reactors, (p,n)/(d,n) in cyclotrons. Specific activity, half-life matching the application, and chemical separation define utility - isotope production is applied nuclear physics.", "how": "Choose production route by target/projectile availability (reactor vs cyclotron). Compute yield from σ, flux, irradiation time (saturation at ~5 half-lives). Separate chemically (hot chemistry); verify purity (radionuclidic + chemical). Match half-life to use.", "keys": ["Joliot-Curie 1934: first artificial isotope.", "Reactors: (n,γ); cyclotrons: (p,n).", "⁹⁹ᵐTc imaging; ¹⁸F PET; ⁶⁰Co therapy.", "Saturation at ~5 half-lives.", "Half-life matched to application."], "reqs": ["Target isotope and reaction.", "Flux and irradiation time.", "Separation chemistry."], "stds": ["Activities in Bq/Ci.", "Specific activity Bq/g."], "cites": ["Joliot F, Curie I. C R Acad Sci 1934;198:254-256.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Activation: saturation with irradiation time.\"\"\"\ndef activity_frac(t, thalf):\n    import math\n    return 1 - math.exp(-math.log(2)*t/thalf)\nfor t in (1, 3, 5):\n    print(f\"  t={t} half-lives: {activity_frac(t, 1)*100:.0f}% of max\")\n"}, {"tier": "Advanced", "g": "Neutrons", "title": "Neutron Physics: Moderation and Capture", "desc": "Fission neutrons are fast (MeV); ²³⁵U fissions best on thermal neutrons (0.025 eV) - moderators (water, heavy water, graphite) slow them by elastic collisions, like billiards with light balls. Hydrogen moderates fastest per collision; heavy water absorbs least.\nCapture cross sections are 1/v - slow neutrons stick. Resonances (e.g., ²³⁸U at eV-keV) parasitic-capture; Doppler broadening with temperature gives reactors negative feedback (safer when hot). Cold/ultracold neutrons probe fundamental physics (lifetime, EDM).", "how": "Choose moderator by slowing-down power × low absorption (D₂O best, H₂O cheapest). Compute moderating ratio; design lattice pitch for resonance escape. Account Doppler feedback in safety analysis. Use 1/v scaling for thermal capture rates.", "keys": ["Fast → thermal: moderation by collisions.", "H₂O cheap; D₂O low-absorption; graphite high-T.", "Capture ∝ 1/v.", "Doppler broadening = negative feedback.", "Resonances parasitic-capture."], "reqs": ["Neutron energy spectrum.", "Moderator properties.", "Temperature for Doppler."], "stds": ["Energies in eV/MeV.", "ξ (avg lethargy gain) dimensionless."], "cites": ["Krane KS. Introductory Nuclear Physics. Wiley; 1987.", "Lamarsh JR, Baratta AJ. Introduction to Nuclear Engineering. 4th ed. Pearson; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Collisions to thermalize (2 MeV → 0.025 eV).\"\"\"\nimport math\ndef n_coll(xi):\n    return math.log(2e6/0.025)/xi\nfor name, xi in [(\"H\", 1.0), (\"D\", 0.725), (\"C\", 0.158)]:\n    print(f\"  {name}: {n_coll(xi):.0f} collisions\")\n"}, {"tier": "Advanced", "g": "Reactors", "title": "Chain Reactions and Criticality", "desc": "k_eff = neutrons produced / neutrons lost: < 1 subcritical (dies), = 1 critical (steady), > 1 supercritical (grows). Each fission's ~2.4 neutrons must replace exactly one - the rest leak or capture. Delayed neutrons (0.65% from fission fragments, seconds late) make control possible - without them reactors couldn't be steered.\nFour-factor formula (ηεpf) for infinite media; Fermi age theory adds leakage. Critical mass: enough fissile material that production beats leakage - geometry matters (sphere optimal). Chicago Pile-1 (1942, Fermi) went critical first.", "how": "Compute k_eff via four factors (infinite) with leakage corrections (finite). Ensure delayed-neutron fraction β enables control (reactivity < β for prompt-critical safety). Design geometry for minimal leakage (sphere). Operate with control rods absorbing the excess.", "keys": ["k_eff = 1: critical.", "Delayed neutrons (0.65%) enable control.", "Four-factor formula: ηεpf.", "Critical mass: production beats leakage.", "Fermi's pile 1942: first criticality."], "reqs": ["Fissile inventory and enrichment.", "Geometry/leakage.", "Delayed-neutron fraction."], "stds": ["k_eff dimensionless.", "Reactivity in dollars (ρ/β)."], "cites": ["Fermi E. (Chicago Pile-1, 1942).", "Lamarsh JR, Baratta AJ. Introduction to Nuclear Engineering. 4th ed. Pearson; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Four-factor k_inf.\"\"\"\ndef k_inf(eta, eps, p, f):\n    return eta*eps*p*f\nprint(f\"  η=2.07 ε=1.03 p=0.87 f=0.71: k_inf = {k_inf(2.07,1.03,0.87,0.71):.3f}\")\n"}, {"tier": "Advanced", "g": "Reactors", "title": "Nuclear Reactors: Types", "desc": "PWR (pressurized water, ~155 bar, most common), BWR (boiling water, direct cycle), CANDU (heavy water, natural uranium), RBMK (graphite, Chernobyl type - positive void coefficient, retired design), fast breeders (no moderator, breed ²³⁹Pu from ²³⁸U).\nFuel: UO₂ pellets in zirconium cladding, 3-5% enriched; burnup ~50 GWd/t. Safety: defense in depth (fuel, cladding, vessel, containment), negative coefficients, ECCS. Waste: fission products (~300 y) + actinides (10⁴ y) - geological disposal (Finland's Onkalo).", "how": "Compare types by moderator/coolant/fuel cycle. Evaluate safety coefficients (void, Doppler - must be negative). Manage fuel (enrichment, burnup, refueling). Plan waste: reprocess or direct disposal; site repositories geologically.", "keys": ["PWR most common; BWR, CANDU, fast breeders.", "UO₂ fuel, 3-5% enriched.", "Defense in depth: 4 barriers.", "Negative coefficients required.", "Waste: fission products + actinides."], "reqs": ["Reactor type and parameters.", "Safety coefficients.", "Fuel-cycle choice."], "stds": ["Burnup in GWd/t.", "Enrichment in % U-235."], "cites": ["Lamarsh JR, Baratta AJ. Introduction to Nuclear Engineering. 4th ed. Pearson; 2017.", "IAEA. Nuclear Power Reactors in the World."], "demo": "#!/usr/bin/env python3\n\"\"\"Reactor type summary.\"\"\"\ntypes = {\"PWR\": \"H2O, 155 bar\", \"BWR\": \"H2O boiling\", \"CANDU\": \"D2O, natural U\", \"Fast breeder\": \"no moderator, breeds Pu\"}\nfor t, d in types.items():\n    print(f\"  {t:13s}: {d}\")\n"}, {"tier": "Advanced", "g": "Fusion", "title": "Controlled Fusion: Magnetic and Inertial", "desc": "Fusion needs 10⁸ K (D-T): magnetic confinement (tokamaks - ITER, stellarators) holds plasma with fields; inertial confinement (NIF lasers) implodes pellets. Lawson criterion: nτ > 10²⁰ s/m³ (D-T). NIF achieved ignition (2022) - more fusion energy out than laser in.\nD-T is easiest (lowest T) but breeds tritium from lithium blankets and makes 14 MeV neutrons (materials challenge). D-D and p-¹¹B are harder but cleaner - the long-term dreams. Fusion's fuel is seawater; its waste is helium.", "how": "Evaluate Lawson nτT for the scheme; compare to 10²⁰-10²¹ targets. Choose D-T for first plants (tritium breeding ratio > 1 required). Manage 14 MeV neutron damage (reduced-activation steels). Track Q (fusion power / input) - ITER targets Q = 10.", "keys": ["10⁸ K needed for D-T.", "Tokamaks/stellarators: magnetic; NIF: inertial.", "Lawson: nτ > 10²⁰ s/m³.", "NIF ignition 2022.", "Fuel seawater; ash helium."], "reqs": ["Confinement scheme.", "nτT triple product.", "Tritium breeding ratio."], "stds": ["T in keV; nτ in s/m³.", "Q dimensionless."], "cites": ["ITER Organization. ITER Technical Basis.", "NIF. Ignition announcement, DOE; 2022."], "demo": "#!/usr/bin/env python3\n\"\"\"Lawson check (toy).\"\"\"\ndef lawson(n, tau):\n    return n*tau\nprint(f\"  n=1e20/m³, τ=1s: nτ = {lawson(1e20, 1):.0e} (need >1e20)\")\n"}, {"tier": "Advanced", "g": "Tools", "title": "Particle Accelerators", "desc": "Accelerators probe nuclei and make isotopes: electrostatic (Van de Graaff, Tandem - MV), cyclotrons (spiral resonance, tens of MeV - PET isotope workhorses), linacs, synchrotrons (GeV, colliders). Lawrence's cyclotron (1930, Nobel 1939) started it.\nRadiofrequency cavities phase-stable bunches; magnets steer and focus (strong focusing - Courant/Snyder 1952). Applications: nuclear physics, isotope production, materials analysis (RBS, PIXE), cancer therapy (protons/carbon ions - Bragg peak).", "how": "Choose type by energy/particle (cyclotron for light ions, linac for electrons). Compute magnetic rigidity (Bρ = p/q) for beamlines. Exploit the Bragg peak for hadron therapy (dose at depth). Maintain vacuum and RF phase stability.", "keys": ["Cyclotron 1930: the first practical.", "RF cavities + magnets: the toolkit.", "Bρ = p/q: beam rigidity.", "Bragg peak enables hadron therapy.", "Isotopes, analysis, physics, medicine."], "reqs": ["Particle and energy.", "Magnetic lattice design.", "Vacuum level."], "stds": ["Energies in eV/MeV/GeV.", "Bρ in T·m."], "cites": ["Lawrence EO, Livingston MS. Phys Rev 1932;40:19-35.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Cyclotron frequency.\"\"\"\ndef f_cyc(B_T, q_over_m):\n    return q_over_m*B_T/(2*3.1416)\nprint(f\"  proton, B=1T: f = {f_cyc(1, 9.58e7)/1e6:.1f} MHz\")\n"}, {"tier": "Advanced", "g": "Tools", "title": "Detectors: Counting Radiation", "desc": "Gas detectors (Geiger-Müller: avalanches count particles; proportional counters measure energy), scintillators (NaI(Tl), plastic - light from radiation, PMTs read out), semiconductors (HPGe: keV resolution for γ spectroscopy; silicon for charged particles).\nChoose by need: GM for surveying, NaI for cheap γ spectra, HPGe for precise γ IDs, liquid scintillation for tritium/¹⁴C. Dead time, efficiency calibration, and background shielding (lead, underground labs) complete the practice.", "how": "Match detector to radiation/energy (HPGe for γ IDs, GM for surveys). Calibrate efficiency vs energy with standard sources. Correct dead time at high rates. Shield background (lead castle; cosmic veto underground). Report with uncertainties.", "keys": ["GM: counts; HPGe: precise γ spectra.", "Scintillators: fast, cheap spectra.", "Semiconductors: best energy resolution.", "Efficiency calibration required.", "Background shielding essential."], "reqs": ["Radiation type/energy.", "Efficiency calibration.", "Background measurement."], "stds": ["Resolution as FWHM in keV.", "Efficiency vs energy curves."], "cites": ["Knoll GF. Radiation Detection and Measurement. 4th ed. Wiley; 2010.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Detector choice by task.\"\"\"\ntasks = {\"survey\": \"GM counter\", \"γ ID\": \"HPGe\", \"fast timing\": \"plastic scintillator\", \"tritium\": \"liquid scintillation\"}\nfor t, d in tasks.items():\n    print(f\"  {t:12s} -> {d}\")\n"}, {"tier": "Advanced", "g": "Applied", "title": "Nuclear Medicine: Imaging and Therapy", "desc": "Imaging: ⁹⁹ᵐTc (140 keV γ, 6 h - 80% of scans), PET (¹⁸F annihilation 511 keV pairs, coincidence detection), SPECT (rotating γ cameras). Tracers follow biochemistry - FDG maps glucose metabolism (cancer lights up).\nTherapy: ¹³¹I (thyroid), ⁶⁰Co/LINAC γ (external beam), targeted α (²²⁵Ac, ²¹³Bi - short range, devastating to cells), boron neutron capture. Theranostics pairs imaging and therapy isotopes of one element.", "how": "Choose isotope by half-life (match procedure), emission (γ for imaging, α/β for therapy), and chemistry (targeting). Compute dosimetry (MIRD). For PET, reconstruct from coincidence lines; for therapy, plan dose to tumor vs tissue. Handle as unsealed sources (contamination control).", "keys": ["⁹⁹ᵐTc: 80% of nuclear imaging.", "PET: 511 keV coincidence pairs.", "FDG maps metabolism.", "¹³¹I thyroid; α-targeted therapy.", "Theranostics: image + treat."], "reqs": ["Isotope half-life/emission.", "Targeting chemistry.", "Dosimetry calculation."], "stds": ["Activities in MBq/GBq.", "Doses in Gy (MIRD)."], "cites": ["Knoll GF. Radiation Detection and Measurement. 4th ed. Wiley; 2010.", "SNMMI. Procedure guidelines."], "demo": "#!/usr/bin/env python3\n\"\"\"⁹⁹ᵐTc remaining after time.\"\"\"\nimport math\ndef frac(t_h, thalf=6.0):\n    return 0.5**(t_h/thalf)\nfor t in (6, 12, 24):\n    print(f\"  after {t:2d} h: {frac(t)*100:.1f}% remains\")\n"}, {"tier": "Advanced", "g": "Applied", "title": "Radiocarbon Dating and Applications", "desc": "¹⁴C (5730 y half-life) is made by cosmic rays (¹⁴N(n,p)¹⁴C), oxidizes to CO₂, and enters life at atmospheric ratio; death stops uptake, the clock starts. Libby (Nobel 1960); AMS now dates milligrams to 50,000 years.\nCalibration needed: atmospheric ¹⁴C varied (dendrochronology curves, IntCal). Bomb carbon (1960s tests doubled ¹⁴C) dates recent tissues forensically. Other clocks: K-Ar (rocks), U-Pb (Earth's age 4.55 Gyr), ²¹⁰Pb (recent sediments).", "how": "Measure ¹⁴C/¹²C by AMS; calibrate with IntCal curves (dendro-matched). Check contamination (modern carbon is the enemy); pretreat (acid-base-acid). Choose the clock by age range: ¹⁴C < 50 kyr, K-Ar/U-Pb for geology.", "keys": ["¹⁴C: 5730 y, cosmic-ray made.", "Death starts the clock.", "AMS dates milligrams to 50 kyr.", "Calibrate (IntCal) - atmosphere varied.", "Bomb carbon dates modern tissues."], "reqs": ["Sample carbon mass.", "Contamination control.", "Calibration curve."], "stds": ["Ages as cal BP with ±.", "IntCal version cited."], "cites": ["Libby WF. Radiocarbon Dating. 2nd ed. Chicago; 1955.", "Reimer PJ et al. Radiocarbon 2020;62:725-757 (IntCal20)."], "demo": "#!/usr/bin/env python3\n\"\"\"Radiocarbon age from remaining fraction.\"\"\"\nimport math\ndef age_yr(frac, thalf=5730):\n    return -thalf*math.log(frac)/math.log(2)\nfor f in (0.5, 0.25, 0.1):\n    print(f\"  {f*100:.0f}% modern: {age_yr(f):.0f} years\")\n"}, {"tier": "Advanced", "g": "Theory", "title": "The Strong Force and QCD (Introduction)", "desc": "Nucleons are quarks (uud proton, udd neutron) bound by gluons - quantum chromodynamics. Color charge (r/g/b), asymptotic freedom (weak at short distance - Gross/Politzer/Wilczek, Nobel 2004), confinement (only colorless hadrons escape).\nResidual strong force (pion exchange, Yukawa 1935) binds nuclei - the van der Waals of QCD. Lattice QCD computes hadron masses from first principles; quark-gluon plasma (RHIC/LHC) recreates the microsecond-old universe.", "how": "Count quarks for hadron quantum numbers (baryons qqq, mesons q q̄). Apply asymptotic freedom at high Q² (parton model); confinement at low energies (effective theories). Compute with lattice QCD for non-perturbative results; use Yukawa potential for nuclear binding estimates.", "keys": ["Quarks + gluons = QCD.", "Asymptotic freedom; confinement.", "Nobel 2004 (Gross/Politzer/Wilczek).", "Nuclear force = residual QCD.", "Lattice QCD computes from first principles."], "reqs": ["Quark content.", "Energy scale (perturbative?).", "Color-singlet check."], "stds": ["Energies in MeV/GeV.", "α_s running cited."], "cites": ["Gross DJ et al. (Nobel 2004).", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Hadron quark content.\"\"\"\nhadrons = {\"proton\": \"uud\", \"neutron\": \"udd\", \"pion+\": \"u d̄\", \"J/ψ\": \"c c̄\"}\nfor name, q in hadrons.items():\n    print(f\"  {name:8s}: {q}\")\n"}, {"tier": "Advanced", "g": "Exotic", "title": "Exotic Nuclei and the Driplines", "desc": "Far from stability: halo nuclei (¹¹Li - two neutrons orbiting far out, matter radius of lead), Borromean systems (bound as three, unbound as two), proton emitters, two-proton radioactivity. Driplines mark where separation energies turn negative - mapped by fragment separators (FRIB, RIKEN).\nMagic numbers shift far from stability (N = 16 emerges, N = 20 fades - island of inversion); superheavies (Z = 114-118) exist by shell stabilization. Exotic beams probe the r-process path - the elements' birthplace.", "how": "Produce via fragmentation/fission of fast beams; separate in-flight. Measure masses (traps, TOF), radii (interaction cross sections), decays. Map driplines from S_n/S_p systematics. Test shell evolution against large-scale models.", "keys": ["Halo nuclei: extended neutron clouds.", "Driplines: separation energy = 0.", "Magic numbers shift far from stability.", "Superheavies by shell stabilization.", "FRIB/RIKEN map the extremes."], "reqs": ["Production mechanism.", "Separation-energy data.", "Beam intensity."], "stds": ["S_n/S_p in MeV.", "Radii in fm."], "cites": ["Tanihata I et al. Phys Rev Lett 1985;55:2676-2679.", "Krane KS. Introductory Nuclear Physics. Wiley; 1987."], "demo": "#!/usr/bin/env python3\n\"\"\"Halo check: matter radius vs A^(1/3).\"\"\"\ndef R(A): return 1.2*A**(1/3)\nprint(f\"  ¹¹Li measured ~3.5 fm vs {R(11):.1f} fm expected -> halo\")\n"}, {"tier": "Advanced", "g": "Astro", "title": "Nuclear Astrophysics: Nucleosynthesis", "desc": "Element origins: Big Bang (H, He, Li), stellar fusion (C through Fe), s-process (AGB stars, slow neutron capture - half the heavy elements), r-process (neutron-star mergers, rapid - the other half, confirmed by GW170817's kilonova), p-process (rare proton-rich).\nB²FH (1957) laid it out; modern work measures the key reaction rates (underground labs: LUNA) and observes mergers (gravitational waves + light). Your body's iron came from a supernova; its gold from colliding neutron stars.", "how": "Assign each isotope to its process (s/r/p/Big Bang/stellar). Compute reaction networks with measured rates (REACLIB). Compare predicted abundances to solar/meteoritic. Use kilonova light curves to weigh r-process ejecta.", "keys": ["Big Bang: H, He, Li.", "Stars: C to Fe by fusion.", "s-process (AGB) + r-process (mergers): heavy elements.", "GW170817 confirmed r-process site.", "B²FH 1957: the founding paper."], "reqs": ["Reaction-rate data.", "Stellar/merger model.", "Abundance observations."], "stds": ["Abundances vs Si = 10⁶.", "Rates in cm³/mol/s."], "cites": ["Burbidge EM et al. Rev Mod Phys 1957;29:547-650.", "Abbott BP et al. (GW170817). Phys Rev Lett 2017;119:161101."], "demo": "#!/usr/bin/env python3\n\"\"\"Element origin assignment.\"\"\"\norigins = {\"H\": \"Big Bang\", \"C\": \"stars\", \"Fe\": \"stars\", \"Au\": \"neutron mergers\", \"Eu\": \"r-process\"}\nfor el, o in origins.items():\n    print(f\"  {el:3s}: {o}\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-NUCPHS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||false;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-NUCPHS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-nuclear-physics-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('nuclear-physics',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
